// TH16 v1.00a Stage 4 mid-stage wave.
// Source: st04.ecl.txt MainSub03:1545-1564 (entry);
//         GirlB01:854-878 and GirlB01_at:880-930 (dependencies).
// Source and target lines are noted next to the corresponding code.

const TH16_RICE: int = 480;   // etSprite(0, 8, 6): source type 8, color 6

const TIME_LIMIT: int = 2224;      // 120 opening buffer + 1750 source window + tail (see report)
const OPENING_BUFFER: int = 120;

// Source GirlB01_at EX, per bullet:
//   etEx(0,0,2,1,-999999,-999999,-999999)  ANIM a=1: birth retreat 4*initial speed
//   etEx(0,0,4,1200,-999999,0.01,1.9634954) ACCEL a=1200, r=0.01, fixed direction 5*pi/8
// Birth slowdown/no-judgement window is omitted by policy; the retreat itself is kept
// through sh_dist and the ACCEL starts at the first effect update after birth.
xformdef RICE_DRIFT {
    @1200 set_gravity(-0.0038268fx, 0.0092388fx);   // 0.01 * (cos 112.5deg, sin 112.5deg)
    set_gravity(0fx, 0fx);
}

// Source GirlB01_at:880-930.
async sub girl_b01_at() {
    var rank: int = global(GVAR_RANK);
    // etCount(0, [-1], 1): E/N 16, H/L 32; etSpeed(0, [-1.0], 1.0) single layer.
    var count: int = 16;
    var speed: fx = 1.0fx;
    var gap: int = 40;                    // !LO 20, others 40
    var volleys: int = 4;                 // diffI($C, 1, 4, 4, 4)
    if rank == RANK_HARD { count = 32; speed = 2.0fx; }
    if rank == RANK_LUNATIC { count = 32; speed = 2.5fx; gap = 20; }
    if rank == RANK_EASY { volleys = 1; }
    var retreat: fx = 0fx - speed * 4fx;  // ANIM a=1: position -= 4 * initial velocity

    sh_reset(0);                          // etNew(0)
    sh_sprite(0, TH16_RICE, 6);           // etSprite(0, 8, 6)
    sh_aim(0, 0);                         // etAim(0, 3): fixed-direction ring
    sh_ring(0, 1);
    sh_count(0, count, 1);
    sh_speed(0, speed, 0fx);
    sh_dist(0, retreat);
    sh_xform(0, RICE_DRIFT);

    var a: int = 16384;                   // %A = 1.570796f (90deg)
    for i in 0..volleys {
        sh_angle(0, a as angle, 0deg);    // etAngle(0, %A, 0.0f)
        a = a + 40503;                    // %A += 3.883222f  (0.618034 turn)
        sh_fire(0);                       // etOn(0)
        wait(gap);
    }
}

// Source GirlB01:854-878 (drops and ANM setup omitted by policy).
async sub girl_b01() {
    set_invuln(65535);
    set_hurtbox(16fx);                    // setHurtbox(32,32): circle radius 32*0.5
    set_hitbox(12fx);                     // setHitbox(24,24): circle radius 24*0.5
    move_vel(0, 90deg, 3.3fx, EASE_LINEAR);       // moveVel(1.5707964, 3.3)
    move_speed(80, 0fx, EASE_QUAD_IN);            // moveVelTime(80, 1, -999999, 0.0)
    spawn girl_b01_at();                          // @GirlB01_at() async
    wait(240);
    move_vel(0, aim_player(), 0fx, EASE_LINEAR);  // moveVel(%ANGLE_PLAYER, 0.0)
    move_speed(80, 1fx, EASE_QUAD_IN);            // moveVelTime(80, 1, -999999, 1.0)
    wait(60);
    loop { wait(1000); }                          // GirlB01_456 / GirlB01_476 wait loop
}

// Source MainSub03:1545-1564: five rounds of five enmCreateF("GirlB01", y=-32).
sub wave() {
    for round in 0..5 {
        _ = spawn_enemy(-160fx, -32fx, 800, 0, 1000, 0, girl_b01);
        wait(70);
        _ = spawn_enemy(90fx, -32fx, 800, 0, 1000, 0, girl_b01);
        wait(70);
        _ = spawn_enemy(-90fx, -32fx, 800, 0, 1000, 0, girl_b01);
        wait(70);
        _ = spawn_enemy(160fx, -32fx, 800, 0, 1000, 0, girl_b01);
        wait(70);
        _ = spawn_enemy(0fx, -32fx, 800, 0, 1000, 0, girl_b01);
        wait(70);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    wave();
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
